// th14_s4_b9 — TH14 v1.00b st04bs2.ecl BossB2 (nonspell, route B / BossB).
// source="th14"; ranks 0..3 (E/N/H/L). Native timeout slot0 = 2700 frames from timerReset.
//
// Source-shape summary (st04bs2.ecl.txt:138-191 + BossB2_at:193-224):
//   entry: timerReset(T0) -> cleanup/movePosTime(60,4,0,128) -> moveLimit(0,128,280,64)
//          -> setInterrupt(0,2300,2700,"BossBCard2") -> wait(120) -> %F0=0.017453
//   loop : @BossB2_at() (10 waves, 8 frames apart) -> moveRand(60,4,1.0) -> %F0*=-1
//          -> wait(120 E/N/H, 60 L) -> repeat (interrupt/HP jumps to BossBCard2)
//   wave : fixed full ring, N=12/24/28/32 (E/N/H/L), all speed 0.4, etDist 32,
//          birth ANIM 4*velocity back-offset, then three sequential ANGLE_ACCEL:
//          (#1) a=60 r=+0.05 s=%F0 ; (#2) a=60 r=-0.05 s=-%F0 ; (#3) a=60 r=+0.01 s=0.
//
// Approved omissions (task/共用取舍): item drops, anmSelect/anmSetMain, playSound, lifeMarker,
// stars, $CAPTURE/$MISS/$BOMB bookkeeping, spellEnd/funcSet(0)/laserCancel (unknown in fresh
// standalone), and killAllAsync/enmKillAll/etCancel/etClear at entry (they target external
// previous-card async/bullets; standalone entry state has none and they must not reach the
// control enemy). The 4*velocity ANIM back-offset is folded into sh_dist (32 - 4*0.4 = 30.4).
// No funcSet/funcCall special functions are used by this attack.

const TH14_NOTE_PURPLE: int = 1024;   // native type 41 (colour 0); see transcribe/th14/touhou-bullets.ecl

const TIME_LIMIT: int = 3324;         // 120 opening + 3200 window + 4 startup (task literal)
const OPENING_BUFFER: int = 120;      // shell buffer; source T0 begins when source_boss first runs
const NATIVE_TIMEOUT: int = 2700;     // setInterrupt slot0 time from timerReset
const SRC_LIMIT_X: fx = 140fx;        // moveLimit(0,128,280,64): x in [-140,140]
const SRC_MIN_Y: fx = 96fx;           // y in [96,160]
const SRC_MAX_Y: fx = 160fx;
const SRC_IN_X: fx = 70fx;            // direction inner band = centre +/- width/4
const SRC_IN_Y_HI: fx = 144fx;        // direction inner band = centre +/- height/4 (112..144)
const SRC_IN_Y_LO: fx = 112fx;

// ---- bullet EX: three sequential ANGLE_ACCEL phases (type 8, a=60 each) ----
// Source async=0 => effect cursor waits, so phases run one after another. 1deg == 0.017453 rad.
// Parameter present so the emitter binds by value (shared program) instead of
// materialising the zero-arg constant sequence into task locals.
xformdef WOBBLE_P(_phase: int) {   // %F0 = +0.017453
    set_accel(0.05fx);
    set_ang_vel(1deg);
    @60 add_speed(0fx);      // #1 duration 60
    set_accel(-0.05fx);
    set_ang_vel(-1deg);
    @60 add_speed(0fx);      // #2 duration 60
    set_accel(0.01fx);
    set_ang_vel(0deg);
    @60 add_speed(0fx);      // #3 duration 60
    set_accel(0fx);          // end of #3: freeze speed at ~1.0, no further turn
}
xformdef WOBBLE_N(_phase: int) {   // %F0 = -0.017453
    set_accel(0.05fx);
    set_ang_vel(-1deg);
    @60 add_speed(0fx);
    set_accel(-0.05fx);
    set_ang_vel(1deg);
    @60 add_speed(0fx);
    set_accel(0.01fx);
    set_ang_vel(0deg);
    @60 add_speed(0fx);
    set_accel(0fx);
}

// ---- moveRand(60,4,1.0) recipe (transcribe/th18/movement.md sample, limit 280x64) ----
// Shared slots: int0 = next step count, fx0/fx1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }         // s0=1.0 => (60-k)/60
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < 0fx - SRC_LIMIT_X { nx = 0fx - SRC_LIMIT_X; }
    if nx > SRC_LIMIT_X { nx = SRC_LIMIT_X; }
    if ny < SRC_MIN_Y { ny = SRC_MIN_Y; }
    if ny > SRC_MAX_Y { ny = SRC_MAX_Y; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // signed unit random * pi; x<->player side pick + y abs/neg, then +/-pi/2 guard.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < 0fx - SRC_IN_X {
        a = r / 3;                                     // side: +/-60deg
    } else if $self_x > SRC_IN_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }                // right side explicitly normalized
    } else {
        a = r / 4;                                     // centre: +/-45deg ...
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < SRC_IN_Y_LO {
        if a < 0 { a = -a; }
    } else if $self_y > SRC_IN_Y_HI {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- one BossB2_at wave ----
sub boss_fire_wave(ways: int, dir: int) {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_PURPLE, 0);   // etSprite(0,41,0)
    sh_aim(0, 0);                        // etAim(0,3): fixed-direction ring
    sh_ring(0, 1);
    sh_count(0, ways, 1);                // etCount ways, 1 layer
    sh_angle(0, rand(65536) as angle, 0deg);  // etAngle(%RANDRAD, .0327): per-wave random base
    sh_speed(0, 0.4fx, 0fx);             // etSpeed(0.4,1.0), M=1 => 0.4
    sh_dist(0, 30.4fx);                  // etDist 32 minus ANIM 4*0.4 back-offset
    if dir > 0 { sh_xform(0, WOBBLE_P(0)); } else { sh_xform(0, WOBBLE_N(0)); }
    sh_fire(0);
}

// ---- real Boss (invulnerable training shell keeps body box + source motion/limits) ----
async sub source_boss() {
    set_invuln(65535);
    set_hitbox(24fx);                    // BossB entry setHitbox(48,48) -> radius 24
    set_hurtbox(24fx);
    // entry: anchor is previous segment's fixed endpoint (0,144); movePosTime(60,4,0,128)
    move_vel(0, 0deg, 0fx, EASE_LINEAR); // moveVel/moveVelTime reset (fresh spawn: no-op)
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);                           // entry wait(120); source T0 at task start

    var t: int = 120;                    // source frames since timerReset
    var dir: int = 1;                    // %F0 sign, flips after each BossB2_at
    var rk: int = global(GVAR_RANK);
    var ways: int = 12;
    var period: int = 120;
    if rk == RANK_NORMAL { ways = 24; }
    else if rk == RANK_HARD { ways = 28; }
    else if rk >= RANK_LUNATIC { ways = 32; period = 60; }

    while t < NATIVE_TIMEOUT {
        for j in 0..10 {                 // BossB2_at: 10 waves, 8 frames apart
            if t >= NATIVE_TIMEOUT { break; }
            boss_fire_wave(ways, dir);
            wait(8);
            t = t + 8;
        }
        if t >= NATIVE_TIMEOUT { break; }
        card_move_rand();                // moveRand(60,4,1.0)
        dir = -dir;                      // %F0 = %F0 * -1
        for i in 0..period {             // wait(120/60) with source-movement ticks armed
            if t >= NATIVE_TIMEOUT { break; }
            wait(1);
            card_arm_next_step();
            t = t + 1;
        }
    }
    // native timeout: stop firing, no next attack; bullets remain as the tail.
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 144fx, 12300, 0, 0, 0, source_boss);  // lifeSet 12300, anchor (0,144)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
